/bin/bash -c "node --input-type=module <<'NODE'
import { spawnSync } from 'node:child_process';

const alphabet = Array.from(\"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_ -"'!@#$%''^&*()[]{};:'"'\\\"\\\\/?.,+=~"'`'"\\n\\t你好Üßé\")
const normalize = (text) => text.replace(/test17_executable/g, 'PROG').replace(/test17\\.mjs/g, 'PROG')

function randomInt(max) {
  return Math.floor(Math.random() * max)
}

function randomString() {
  const length = randomInt(8)
  let value = ''
  for (let i = 0; i < length; i += 1) {
    value += alphabet[randomInt(alphabet.length)]
  }
  return value
}

for (let caseIndex = 0; caseIndex < 100; caseIndex += 1) {
  const parts = []
  const partCount = 1 + randomInt(5)
  for (let i = 0; i < partCount; i += 1) {
    parts.push(randomString())
  }

  const arg = parts.join(',')
  const args = ['--a', arg]
  const ref = spawnSync('/workspace/dataset/test17_executable', args, { encoding: 'utf8' })
  const mine = spawnSync('node', ['/output/test17.mjs', ...args], { encoding: 'utf8' })
  const same = ref.status === mine.status && normalize(ref.stdout) === normalize(mine.stdout) && normalize(ref.stderr) === normalize(mine.stderr)

  if ("'!same) {
    console.log('"'MISMATCH', JSON.stringify(args))
    console.log('REF STATUS', ref.status, 'MINE STATUS', mine.status)
    console.log('--- REF STDOUT ---')
    process.stdout.write(ref.stdout)
    console.log('--- MINE STDOUT ---')
    process.stdout.write(mine.stdout)
    console.log('--- REF STDERR ---')
    process.stdout.write(ref.stderr)
    console.log('--- MINE STDERR ---')
    process.stdout.write(mine.stderr)
    process.exit(1)
  }
}

